--ink)}.email-panel label{overflow-wrap:anywhere}.email-panel input,.email-panel textarea{max-width:100%;min-width:0}.email-dns-list article{display:flex;align-items:start;gap:18px;justify-content:space-between;padding:18px 0;border-top:1px solid var(--line)}.email-dns-list article>div{min-width:0}.email-dns-list strong{font-size:13px;display:block;margin-bottom:6px}.email-dns-list code{display:block;color:var(--muted)}.email-dns-list p{font-size:12px;margin:9px 0 0;color:var(--muted)}.email-counts{display:flex;gap:8px;flex-wrap:wrap}.email-test-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,280px) auto;gap:18px;align-items:end;margin:24px 0;padding:22px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.email-test-form h3{font-size:14px;margin-bottom:7px}.email-test-form p{margin:0}.email-history{max-width:100%;border:1px solid var(--line);border-radius:10px}.email-history table{min-width:720px}.email-history td{vertical-align:top}.email-history td strong{font-size:12px;color:var(--ink)}.email-history td small{display:block;max-width:260px;white-space:normal;overflow-wrap:anywhere;margin-top:6px}.email-history td:nth-child(4){max-width:170px;font-size:11px}.email-retry-form{border:1px solid var(--line);border-radius:12px;padding:20px;margin-top:22px;background:var(--bg)}.email-retry-form h3{font-size:15px}.email-retry-form label{max-width:380px}.email-retry-form .button-row{margin-top:18px}.email-suppression-list article{display:flex;gap:18px;align-items:start;justify-content:space-between;padding:18px 0;border-bottom:1px solid var(--line)}.email-suppression-list article>div{min-width:0;overflow-wrap:anywhere}.email-suppression-list strong{font-size:12px}.email-suppression-list p{font-size:12px;margin:7px 0;color:var(--muted)}.email-suppression-list small{color:var(--muted);font-size:10px}.email-suppression-list button{flex-shrink:0}.email-suppression-form{max-width:790px;border-top:1px solid var(--line);margin-top:25px;padding-top:25px}.email-suppression-form h3{font-size:15px;margin-bottom:0}.email-suppression-form>button{align-self:start}.email-suppression-form>label{max-width:480px}
@media(max-width:1000px){.email-test-form{grid-template-columns:1fr 1fr}.email-test-form>div{grid-column:1/-1}.email-test-form>.button{justify-self:start}.email-confirmation{grid-template-columns:1fr}.emails-admin .page-heading{display:block}.emails-admin .page-heading>.button-row{margin-top:18px}}@media(max-width:620px){.email-summary-grid{grid-template-columns:1fr;gap:10px}.email-summary-grid>div{padding:18px}.email-summary-grid strong{font-size:20px;margin:6px 0}.email-panel{padding:20px}.email-form-grid{grid-template-columns:1fr;gap:17px}.email-test-form{grid-template-columns:1fr}.email-dns-list article{flex-direction:column;gap:10px}.email-section-nav{gap:8px 18px}.email-section-nav button{margin-left:0}.email-suppression-list article{flex-direction:column;gap:12px}.email-panel>.section-heading{flex-wrap:wrap}.email-advanced{padding:14px}.email-setup-list{font-size:12px}.email-confirmation .button{white-space:normal;text-align:center}.emails-admin .button-row{gap:8px}}
</style>
